    # Bo'sh joylashuv kod default'idan oladi — unda SIT bor.
    for placement in ("main", "footer_platform"):
        rows = LandingNavItem.objects.filter(placement=placement)
        if not rows.exists():
            continue
        if rows.filter(models.Q(key="sit") | models.Q(custom_url__in=(SIT_PATH, SIT_PATH.rstrip("/")))).exists():
            continue
        last = rows.order_by("-order").values_list("order", flat=True).first() or 0
        LandingNavItem.objects.create(placement=placement, key="sit", label=SIT_LABEL, order=last + 1)


